Add Default and Display trait implementations to src/lib.rs.

// Color: default is black (0, 0, 0)
impl Default for Color {
    fn default() -> Self { Color { r: 0, g: 0, b: 0 } }
}

// Color: display as "rgb(r, g, b)"
impl std::fmt::Display for Color {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "rgb({}, {}, {})", self.r, self.g, self.b)
    }
}

// Point: default is origin (0.0, 0.0)
impl Default for Point {
    fn default() -> Self { Point { x: 0.0, y: 0.0 } }
}

// Point: display as "(x, y)"
impl std::fmt::Display for Point {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "({}, {})", self.x, self.y)
    }
}

